import { decodePositiveIntegerSeq, encodePositiveIntegerSeq } from '@pohodnik/seq-encoder';

// НЕ МЕНЯТЬ!!!
const latLonPrecision = 7;
const latLonMultiply = 1e5;
const timestampDiv = 1e3;
const altitudeShift = 450;
const hrShift = 300;
const tempShift = 300;
const cadenceShift = 300;

export const latToInt = (lat: number) =>
  Math.round(+Number(lat).toPrecision(latLonPrecision) * latLonMultiply);
export const altToInt = (alt: number) => Math.round(altitudeShift + alt);
export const timeToInt = (ts: number) => Math.round(ts / timestampDiv);
export const hrToInt = (hr: number) => Math.round(hrShift + hr);
export const tempToInt = (temp: number) => Math.round(tempShift + temp);
export const cadenceToInt = (cad: number) => Math.round(cadenceShift + cad);

export const intToLat = (n: number) => Number(n / latLonMultiply);
export const intToAlt = (n: number) => Number(n - altitudeShift);
export const intToTime = (n: number) => Number(n * timestampDiv);
export const intToHr = (n: number) => Number(n - hrShift);
export const intToTemp = (n: number) => Number(n - tempShift);
export const intToCadence = (n: number) => Number(n - cadenceShift);

export interface IGpxDataSequences {
  latitudes: number[] | null;
  longitudes: number[] | null;
  altitudes: number[] | null;
  timestamps: number[] | null;
  heartRates: number[] | null;
  temperatures: number[] | null;
  cadences: number[] | null;
}

export interface IGpxDataSequencesStringOptions {
  latitudes: string | null;
  longitudes: string | null;
  altitudes?: string | null;
  timestamps?: string | null;
  heart_rates?: string | null;
  temperatures?: string | null;
  cadences?: string | null;
}

export const getGpxDataSequencesFromStrings = (
  opts: IGpxDataSequencesStringOptions,
): IGpxDataSequences => {
  return {
    latitudes: opts.latitudes ? decodePositiveIntegerSeq(opts.latitudes).map(intToLat) : null,
    longitudes: opts.longitudes ? decodePositiveIntegerSeq(opts.longitudes).map(intToLat) : null,
    timestamps: opts.timestamps ? decodePositiveIntegerSeq(opts.timestamps).map(intToTime) : null,
    altitudes: opts.altitudes ? decodePositiveIntegerSeq(opts.altitudes).map(intToAlt) : null,
    heartRates: opts.heart_rates ? decodePositiveIntegerSeq(opts.heart_rates).map(intToHr) : null,
    temperatures: opts.temperatures
      ? decodePositiveIntegerSeq(opts.temperatures).map(intToTemp)
      : null,
    cadences: opts.cadences ? decodePositiveIntegerSeq(opts.cadences).map(intToCadence) : null,
  };
};

export interface IGpxDataNumbersSequenceOptions {
  latitudes?: number[] | null;
  longitudes?: number[] | null;
  altitudes?: number[] | null;
  timestamps?: number[] | null;
  heartRates?: number[] | null;
  temperatures?: number[] | null;
  cadences?: number[] | null;
}

export const getStringsFromGpxDataSequences = (
  opts: IGpxDataNumbersSequenceOptions,
): IGpxDataSequencesStringOptions => {
  return {
    latitudes: opts.latitudes ? encodePositiveIntegerSeq(opts.latitudes.map(latToInt)) : null,
    longitudes: opts.longitudes ? encodePositiveIntegerSeq(opts.longitudes.map(latToInt)) : null,
    timestamps: opts.timestamps ? encodePositiveIntegerSeq(opts.timestamps.map(timeToInt)) : null,
    altitudes: opts.altitudes ? encodePositiveIntegerSeq(opts.altitudes.map(altToInt)) : null,
    heart_rates: opts.heartRates ? encodePositiveIntegerSeq(opts.heartRates.map(hrToInt)) : null,
    temperatures: opts.temperatures
      ? encodePositiveIntegerSeq(opts.temperatures.map(tempToInt))
      : null,
    cadences: opts.cadences ? encodePositiveIntegerSeq(opts.cadences.map(cadenceToInt)) : null,
  };
};

export const getLatLonEleFromSequencesStrings = (
  opts: Pick<IGpxDataSequencesStringOptions, 'latitudes' | 'longitudes' | 'altitudes'>,
): Array<[number, number] | [number, number, number]> => {
  const latitudes = decodePositiveIntegerSeq(opts.latitudes!).map(intToLat);
  const longitudes = decodePositiveIntegerSeq(opts.longitudes!).map(intToLat);
  const altitudes = opts.altitudes ? decodePositiveIntegerSeq(opts.altitudes).map(intToAlt) : [];
  const res: Array<[number, number] | [number, number, number]> = [];
  latitudes.forEach((lat, i) => {
    const cur: [number, number] | [number, number, number] = [lat, longitudes[i]];
    if (typeof altitudes[i] !== 'undefined') cur.push(altitudes[i]);
    res.push(cur);
  });
  return res;
};
